#include "ssolve/manifest.hpp"

#include <unistd.h>

#include <cstdlib>
#include <fstream>
#include <set>
#include <sstream>
#include <thread>
#include <utility>

#if defined(__APPLE__)
#include <sys/sysctl.h>
#endif
#if defined(__linux__)
#include <sched.h>
#endif

#include "ssolve_build_info.h"  // SSOLVE_GIT_COMMIT and SSOLVE_BUILD_FLAGS, generated by CMake

namespace ssolve {

namespace {

std::string compiler_name() {
#if defined(__clang__)
  return std::string("clang ") + __clang_version__;
#elif defined(__GNUC__)
  return std::string("gcc ") + __VERSION__;
#else
  return "unknown";
#endif
}

#if defined(__APPLE__)

template <class T>
T sysctl_value(const char* name) {
  T value{};
  std::size_t size = sizeof(value);
  if (sysctlbyname(name, &value, &size, nullptr, 0) != 0) return T{};
  return value;
}

void read_platform(Manifest& m) {
  char brand[256] = {};
  std::size_t size = sizeof(brand);
  if (sysctlbyname("machdep.cpu.brand_string", brand, &size, nullptr, 0) == 0) m.cpu_model = brand;
  m.physical_cores = sysctl_value<int>("hw.physicalcpu");
  m.l1d_bytes = sysctl_value<std::int64_t>("hw.l1dcachesize");
  m.l2_bytes = sysctl_value<std::int64_t>("hw.l2cachesize");
  m.l3_bytes = sysctl_value<std::int64_t>("hw.l3cachesize");
  m.mem_bytes = sysctl_value<std::int64_t>("hw.memsize");
}

#else

std::string read_line(const std::string& path) {
  std::ifstream file(path);
  std::string line;
  std::getline(file, line);
  return line;
}

// Parses sysfs cache sizes such as "48K" or "12288K".
std::int64_t parse_cache_size(const std::string& text) {
  if (text.empty()) return 0;
  char* end = nullptr;
  const std::int64_t value = std::strtoll(text.c_str(), &end, 10);
  if (*end == 'K') return value * 1024;
  if (*end == 'M') return value * 1024 * 1024;
  return value;
}

std::string read_cpu_model() {
  std::ifstream file("/proc/cpuinfo");
  std::string line;
  while (std::getline(file, line)) {
    if (line.rfind("model name", 0) == 0) {
      const std::size_t colon = line.find(':');
      if (colon != std::string::npos && colon + 2 <= line.size()) return line.substr(colon + 2);
    }
  }
  return "";
}

int count_physical_cores(int logical_cpus) {
  std::set<std::pair<std::string, std::string>> cores;
  for (int cpu = 0; cpu < logical_cpus; ++cpu) {
    const std::string base = "/sys/devices/system/cpu/cpu" + std::to_string(cpu) + "/topology/";
    const std::string package = read_line(base + "physical_package_id");
    const std::string core = read_line(base + "core_id");
    if (core.empty()) return 0;
    cores.insert({package, core});
  }
  return static_cast<int>(cores.size());
}

void read_caches(Manifest& m) {
  for (int index = 0; index < 8; ++index) {
    const std::string base = "/sys/devices/system/cpu/cpu0/cache/index" + std::to_string(index) + "/";
    const std::string level = read_line(base + "level");
    if (level.empty()) continue;
    const std::string type = read_line(base + "type");
    const std::int64_t size = parse_cache_size(read_line(base + "size"));
    if (level == "1" && type == "Data") m.l1d_bytes = size;
    if (level == "2") m.l2_bytes = size;
    if (level == "3") m.l3_bytes = size;
  }
}

// WSL2 shows a virtual CPU layout, so its core count does not describe the hardware.
bool cpu_layout_is_virtual() {
  const std::string release = read_line("/proc/sys/kernel/osrelease");
  return release.find("microsoft") != std::string::npos || release.find("WSL") != std::string::npos;
}

void read_platform(Manifest& m) {
  m.cpu_model = read_cpu_model();
  m.physical_cores = cpu_layout_is_virtual() ? 0 : count_physical_cores(m.logical_cpus);
  read_caches(m);
  const long pages = sysconf(_SC_PHYS_PAGES);
  const long page_size = sysconf(_SC_PAGESIZE);
  if (pages > 0 && page_size > 0) m.mem_bytes = static_cast<std::int64_t>(pages) * page_size;
}

#endif

}  // namespace

Manifest collect_manifest() {
  Manifest m;
  m.git_commit = SSOLVE_GIT_COMMIT;
  m.flags = SSOLVE_BUILD_FLAGS;
  m.compiler = compiler_name();
  m.eigen_commit = SSOLVE_EIGEN_COMMIT;
  char hostname[256] = {};
  if (gethostname(hostname, sizeof(hostname) - 1) == 0) m.hostname = hostname;
#if defined(__linux__)
  cpu_set_t cpus;
  CPU_ZERO(&cpus);
  if (sched_getaffinity(0, sizeof(cpus), &cpus) == 0) {
    m.affinity.clear();
    for (int cpu = 0; cpu < CPU_SETSIZE; ++cpu) {
      if (CPU_ISSET(cpu, &cpus)) {
        if (!m.affinity.empty()) m.affinity += ",";
        m.affinity += std::to_string(cpu);
      }
    }
  }
#endif
  m.logical_cpus = static_cast<int>(std::thread::hardware_concurrency());
  read_platform(m);
  return m;
}

std::vector<std::string> manifest_columns() {
  return {"git_commit", "cpu_model", "compiler",  "flags",    "logical_cpus",
          "physical_cores", "l1d_bytes", "l2_bytes", "l3_bytes", "mem_bytes", "eigen_commit", "affinity", "hostname"};
}

std::vector<std::string> manifest_values(const Manifest& m) {
  return {m.git_commit,
          m.cpu_model,
          m.compiler,
          m.flags,
          std::to_string(m.logical_cpus),
          std::to_string(m.physical_cores),
          std::to_string(m.l1d_bytes),
          std::to_string(m.l2_bytes),
          std::to_string(m.l3_bytes),
          std::to_string(m.mem_bytes), m.eigen_commit, m.affinity, m.hostname};
}

}  // namespace ssolve
